use std::json
use std::fs

struct Item {
    sku: string,
    qty: int,
    price: float,
}

struct Order {
    id: int,
    customer: string,
    items: Vec<Item>,
    note: Option<string>,
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let parsed = json.parse_string::<Vec<Order>>(text)
    match parsed {
        Ok(orders) => {
            let mut names: Vec<string> = []
            for o in orders {
                names.push(o.customer)
            }
            names.sort()
            names.dedup()
            for n in names {
                let mut sum = 0.0
                for o in orders {
                    if o.customer == n {
                        for it in o.items {
                            sum += (it.qty as float) * it.price
                        }
                    }
                }
                println("${n} ${sum:.2}")
            }
        }
        Err(e) => {
            println("invalid input")
            std::process::exit(1)
        }
    }
}

